package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.fasterxml.jackson.databind.node.ObjectNode;import com.ruoyi.medical.contracts.*;import com.ruoyi.medical.identity.*;import jakarta.servlet.http.HttpServletRequest;import java.math.BigInteger;import java.time.*;import java.util.*;import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.util.function.ThrowingSupplier;
/** Actual MODEL_VERIFICATION lease/token producer. Only a registered original service sees its own queued job metadata. */
public final class FormalVerificationWorkerService {
 private final JdbcTemplate db;private final ServiceCertificateIdentity services;private final TenantTransaction transactions;private final RunTokenAuthority tokens;private final RunTokenPolicyStore policy;private final FormalVerificationJobs jobs;private final FormalInvocationSchema json;private final RunTokenAuthoritySchema runtime;private final long lifetime;
 public FormalVerificationWorkerService(DataSource d,ServiceCertificateIdentity s,TenantTransaction tx,RunTokenAuthority tokens,RunTokenPolicyStore policy,FormalVerificationJobs jobs,FormalInvocationSchema json,RunTokenAuthoritySchema runtime,long lifetime){if(lifetime<2||lifetime>300)throw new IllegalArgumentException("Explicit worker lease lifetime 2..300 required");db=new JdbcTemplate(d);db.setQueryTimeout(5);services=s;transactions=tx;this.tokens=tokens;this.policy=policy;this.jobs=jobs;this.json=json;this.runtime=runtime;this.lifetime=lifetime;}
 private record State(FormalVerificationJobs.Job job,JsonNode dependencies,String status,BigInteger revision,BigInteger generation,String owner,LocalDateTime expires,LocalDateTime now,String invocation,String attempt,String invocationStatus){}
 public JsonNode claim(HttpServletRequest http,String tenant)throws Exception{
  WireValues.uuid(tenant);var service=services.require(http);
  // Bounded live queue. Only actual original service assignments; no arbitrary user-supplied run/step/actor IDs.
  var ids=db.query("SELECT j.verification_id FROM formal_model_verification_job j JOIN system_job_run r ON r.tenant_id=j.tenant_id AND r.run_id=j.run_id AND r.job_type='MODEL_VERIFICATION' AND r.target_kind='CONFIGURATION' AND r.status='RUNNING' JOIN run_step s ON s.tenant_id=j.tenant_id AND s.run_id=j.run_id AND s.step_id=j.step_id LEFT JOIN invocation i ON i.tenant_id=j.tenant_id AND i.run_id=j.run_id AND i.step_id=j.step_id AND i.action_id=j.action_id WHERE j.tenant_id=? AND JSON_CONTAINS(JSON_EXTRACT(j.dependency_snapshot,'$.principal.services'),JSON_OBJECT('service_uri',?)) AND i.invocation_id IS NULL AND (s.status='READY' OR (s.status='RUNNING' AND s.lease_expires_at<=UTC_TIMESTAMP(6))) ORDER BY j.created_at,j.verification_id LIMIT 1",(r,n)->r.getString(1),tenant,service.serviceUri());
  if(ids.isEmpty())return object().put("found",false).putNull("lease");if(ids.size()!=1)bad();State state=state(http,tenant,ids.get(0));long seconds=Math.min(lifetime,policy.read().policy().maximumLifetime().toSeconds());if(seconds<2)throw new TenantAccessException(ErrorCode.ACCESS_DENIED);
  var lease=tokens.claimStep(http,new RunTokenAuthority.ClaimRequest(tenant,state.job.actor(),state.job.run(),state.job.step(),state.revision,Duration.ofSeconds(seconds)));if(!lease.runId().equals(state.job.run())||!lease.stepId().equals(state.job.step())||!lease.owner().equals(service.serviceUri()))bad();
  var result=object().put("verification_id",state.job.verification()).put("run_id",lease.runId()).put("step_id",lease.stepId()).put("lease_generation",lease.generation().toString()).put("revision",lease.revision().toString()).put("expires_at",lease.expiresAt().toString());return object().put("found",true).set("lease",result);
 }
 public JsonNode issue(HttpServletRequest http,String tenant,String verification)throws Exception{
  State s=state(http,tenant,verification);var service=services.require(http);if(!"RUNNING".equals(s.status)||!service.serviceUri().equals(s.owner)||s.expires==null)throw new TenantAccessException(ErrorCode.LEASE_STALE);long remaining=Duration.between(s.now,s.expires).toSeconds()-1;long seconds=Math.min(Math.min(lifetime,policy.read().policy().maximumLifetime().toSeconds()),remaining);if(seconds<1)throw new TenantAccessException(ErrorCode.LEASE_STALE);
  var actions=runtime.permissions(s.dependencies.required("principal")).stream().map(RunTokenAuthoritySchema.Permission::action).distinct().toList();var issued=tokens.issue(http,new RunTokenAuthority.IssueRequest(tenant,s.job.actor(),s.job.run(),s.job.step(),s.generation,actions,Duration.ofSeconds(seconds)));
  var request=json.parse(s.job.request());var model=s.dependencies.required("model");var action=object().put("run_id",s.job.run()).put("step_id",s.job.step()).put("action_id",s.job.action()).put("lease_generation",s.generation.toString()).put("input_sha256",s.job.inputHash()).put("arguments_sha256",s.job.requestHash()).put("kind","MODEL_CALL").put("tool_version",s.job.model()).put("action","model.send").put("purpose","MODEL_VERIFICATION");action.set("scope",json.parse(json.canonical(new PermissionProtocol.Scope(tenant,s.job.project(),"CONFIGURATION",model.required("config_id").textValue()))));
  var out=object().put("verification_id",verification).put("run_id",s.job.run()).put("step_id",s.job.step()).put("token",issued.token()).put("token_expires_at",issued.expiresAt().toString()).put("model_config_revision",s.job.model()).put("context_manifest_id",s.job.context());out.set("worker_action",action);out.set("request_parameters",request.required("request_parameters"));return out;
 }
 public JsonNode status(HttpServletRequest http,String tenant,String verification)throws Exception{State s=state(http,tenant,verification);var out=object().put("verification_id",verification).put("run_id",s.job.run()).put("step_id",s.job.step()).put("step_status",s.status).put("revision",s.revision.toString());if(s.invocation==null)out.putNull("invocation_id");else out.put("invocation_id",s.invocation);if(s.attempt==null)out.putNull("dispatch_attempt_id");else out.put("dispatch_attempt_id",s.attempt);if(s.invocationStatus==null)out.putNull("invocation_status");else out.put("invocation_status",s.invocationStatus);return out;}
 private State state(HttpServletRequest http,String tenant,String verification)throws Exception{
  WireValues.uuid(tenant);WireValues.uuid(verification);var service=services.require(http);var actor=one(db.query("SELECT created_by FROM formal_model_verification_job WHERE tenant_id=? AND verification_id=? AND JSON_CONTAINS(JSON_EXTRACT(dependency_snapshot,'$.principal.services'),JSON_OBJECT('service_uri',?)) LIMIT 2",(r,n)->r.getString(1),tenant,verification,service.serviceUri()));var epochs=one(db.query("SELECT auth_epoch,governance_epoch FROM tenant WHERE tenant_id=? LIMIT 2",(r,n)->new TenantWatermarks(r.getBigDecimal(1).toBigIntegerExact(),r.getBigDecimal(2).toBigIntegerExact()),tenant));
  try(var scope=TenantScope.open(new TenantScope.Identity(tenant,actor,BigInteger.ZERO,epochs.authEpoch(),epochs.governanceEpoch()))){return transactions.execute(ignored->ThrowingSupplier.of(()->{var job=jobs.read(tenant,verification).orElseThrow(()->new TenantAccessException(ErrorCode.CONTENT_MISMATCH));if(!actor.equals(job.actor()))bad();var deps=json.parse(job.dependencies());boolean assigned=false;for(var item:deps.required("principal").required("services"))if(service.serviceUri().equals(item.required("service_uri").textValue()))assigned=true;if(!assigned)throw new TenantAccessException(ErrorCode.ACCESS_DENIED);
   var row=one(db.query("SELECT s.status,s.revision,s.lease_generation,s.lease_owner,s.lease_expires_at,UTC_TIMESTAMP(6),i.invocation_id,a.attempt_id,i.status FROM run_step s JOIN system_job_run j ON j.tenant_id=s.tenant_id AND j.run_id=s.run_id AND j.job_type='MODEL_VERIFICATION' AND j.target_kind='CONFIGURATION' LEFT JOIN invocation i ON i.tenant_id=s.tenant_id AND i.run_id=s.run_id AND i.step_id=s.step_id AND i.action_id=? LEFT JOIN formal_invocation_attempt a ON a.tenant_id=i.tenant_id AND a.invocation_id=i.invocation_id WHERE s.tenant_id=? AND s.run_id=? AND s.step_id=? LIMIT 2",(r,n)->new State(job,deps,r.getString(1),r.getBigDecimal(2).toBigIntegerExact(),r.getBigDecimal(3).toBigIntegerExact(),r.getString(4),r.getTimestamp(5)==null?null:r.getTimestamp(5).toLocalDateTime(),r.getTimestamp(6).toLocalDateTime(),r.getString(7),r.getString(8),r.getString(9)),job.action(),tenant,job.run(),job.step()));var fresh=services.require(http);if(!fresh.serviceUri().equals(service.serviceUri())||!fresh.certificateSha256().equals(service.certificateSha256())||!fresh.trustRevision().equals(service.trustRevision()))throw new TenantAccessException(ErrorCode.ACCESS_DENIED);return row;}).get());}
 }
 private static ObjectNode object(){return new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode();}private static <T>T one(List<T> r){if(r.size()!=1||r.get(0)==null)bad();return r.get(0);}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}
}
